import React from 'react';
import './SocialLinksCard.css';
import { FaXTwitter, FaDribbble, FaInstagram, FaLinkedinIn, FaBehance, FaEnvelope } from 'react-icons/fa6';
import { motion } from 'framer-motion';

const SocialLinksCard = () => {
  return (
    <motion.div
      className="social-grid"
      initial={{ opacity: 0, y: 30 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.6, ease: 'easeOut' }}
    >
      <a href="https://x.com/RohitChand2024" className="social-icon twitter" target="_blank" rel="noopener noreferrer"><FaXTwitter /></a>
      <a href="https://dribbble.com/rohit_chanda" className="social-icon dribbble" target="_blank" rel="noopener noreferrer"><FaDribbble /></a>
      <a href="https://www.instagram.com/rohitchanda007?igsh=ZDNzY2lxY3F5N2tn" className="social-icon instagram" target="_blank" rel="noopener noreferrer"><FaInstagram /></a>
      <a href="www.linkedin.com/in/rohit-chanda" className="social-icon linkedin" target="_blank" rel="noopener noreferrer"><FaLinkedinIn /></a>
      <a href="https://www.behance.net/rohitchanda2" className="social-icon behance" target="_blank" rel="noopener noreferrer"><FaBehance /></a>
      <a href="mailto:rohitchanda2024@gmail.com" className="social-icon email"><FaEnvelope /></a>
    </motion.div>
  );
};

export default SocialLinksCard;
