// src/pages/BlogPost.js

import React from "react";
import { Link, useParams } from "react-router-dom";
import blogData from "../data/blogData";

import BlogMeta from "../components/Blog/BlogMeta";
import BlogContent from "../components/Blog/BlogContent";

import { useBlogTheme } from "../components/Blog/BlogThemeContext";
import { Sun, Moon } from "lucide-react";

import "../components/Blog/BlogPost.css";
import RelatedPosts from "../components/Blog/RelatedPosts";
import { Helmet } from "react-helmet";

const BlogPost = () => {
  const { theme, toggleTheme } = useBlogTheme();
  const { id } = useParams();
  const blog = blogData.find((b) => b.id === id);

  if (!blog) {
    return <div className="not-found">Blog not found.</div>;
  }

  const metaTitle = `${blog.title} | Dev Diary`;
  const metaDescription =
    blog.summary || blog.content.slice(0, 150).replace(/[#*>]/g, "") + "...";
  const canonicalUrl = `https://rohitchanda.in/blog/${blog.id}`;

  <Helmet>
    <title>{metaTitle}</title>
    <meta name="description" content={metaDescription} />
    <link rel="canonical" href={canonicalUrl} />

    {/* Open Graph tags for social sharing */}
    <meta property="og:title" content={metaTitle} />
    <meta property="og:description" content={metaDescription} />
    <meta property="og:url" content={canonicalUrl} />
    <meta property="og:type" content="article" />
    {blog.coverImage && <meta property="og:image" content={blog.coverImage} />}

    {/* Twitter Card (optional) */}
    <meta name="twitter:card" content="summary_large_image" />
    <meta name="twitter:title" content={metaTitle} />
    <meta name="twitter:description" content={metaDescription} />
    {blog.coverImage && <meta name="twitter:image" content={blog.coverImage} />}
  </Helmet>;

  return (
    <div className="blog-post-container">
      <div className="blog-top-bar">
        <div className="blog-nav-links">
          <Link to="/" className="return-btn">
            ← Back to Portfolio
          </Link>
          <Link to="/blog" className="blog-home-btn">
            Blog Home
          </Link>
        </div>
        <button
          className="theme-toggle-button icon-toggle"
          onClick={toggleTheme}
        >
          {theme === "dark" ? <Sun size={18} /> : <Moon size={18} />}
        </button>
      </div>

      {/* 🧠 Blog Header */}
      <div className="blog-header">
        <h2 className="blog-heading">Dev Diary</h2>
        <h3 className=""><BlogContent title={blog.title}/></h3>
      </div>

      {/* 🖼️ Cover Image */}
      {blog.coverImage && (
        <div className="blog-cover-image">
          <img src={blog.coverImage} alt={blog.title} />
        </div>
      )}

      {/* 📄 Blog Layout */}
      <div className="blog-main-grid">
        <aside className="blog-sidebar">
          <BlogMeta author={blog.author} date={blog.date} tag={blog.tag} />
          {/* <BlogMeta attribution={blog.attribution}/> */}
        </aside>

        <section className="blog-body">
          <BlogContent  content={blog.content} />
        </section>
      </div>

      {/* 🔗 Related Posts (full-width below content) */}
      <RelatedPosts currentPostId={blog.id} tags={blog.tag} />
    </div>
  );
};

export default BlogPost;
