// BlogPost.js (modified)
import React, { useState } from "react";
import { Link } from "react-router-dom";
import { useBlogTheme } from "./BlogThemeContext";
import blogPosts from "../../data/blogData";
import { Sun, Moon } from "lucide-react";
import BlogSlider from "./BlogSlider";

import "./BlogPage.css";

const BlogPage = () => {
  const { theme, toggleTheme } = useBlogTheme();
  const [visibleCount, setVisibleCount] = useState(6); // Show 6 blogs initially

  const handleLoadMore = () => {
    setVisibleCount((prev) => prev + 6); // Load 6 more blogs each time
  };

  const visibleBlogs = blogPosts.slice(0, visibleCount);

  return (
    <div className={`blog-page-container ${theme}`}>
      <Link to="/" className="back-to-portfolio">← Back to Portfolio</Link>
      <button className="theme-toggle-button icon-toggle" onClick={toggleTheme}>
        {theme === "dark" ? <Sun size={18} /> : <Moon size={18} />}
      </button>

      <div className="blog-header">
        <h2 className="blog-heading">DEV DIARY</h2>
      </div>

      <BlogSlider />

      <div className="blog-list">
        {visibleBlogs.map((post) => (
          <Link key={post.id} to={`/blog/${post.id}`} className="blog-preview-card">
            <img src={`/images/blog/${post.id}.jpg`} alt={post.title} className="blog-preview-image" />
            <p className="blog-tag">— {post.tag}</p>
            <h3 className="blog-preview-title">{post.title}</h3>
            <div className="blog-preview-meta">
              <span>{post.date}</span>
              <span>— {post.author}</span>
            </div>
          </Link>
        ))}
      </div>

      {visibleCount < blogPosts.length && (
        <div className="load-more-container">
          <button onClick={handleLoadMore} className="load-more-button">Load More</button>
        </div>
      )}
    </div>
  );
};

export default BlogPage;
