import React, { useState, useEffect } from "react";
import { motion, AnimatePresence } from "framer-motion";
import "./BlogSlider.css";
import blogData from "../../data/blogData";
import { useNavigate } from "react-router-dom";

const BlogSlider = () => {
  const navigate = useNavigate();

  const [current, setCurrent] = useState(0);
  const delay = 5000;

  useEffect(() => {
    const interval = setInterval(() => {
      setCurrent((prev) => (prev + 1) % blogData.length);
    }, delay);
    return () => clearInterval(interval);
  }, []);

  return (
    <div className="blog-slider-wrapper">
      <div className="blog-slider">
        <AnimatePresence initial={false} mode="wait">
          <motion.div
            key={current}
            className="blog-slide"
            initial={{ x: 100, opacity: 0 }}
            animate={{ x: 0, opacity: 1 }}
            exit={{ x: -100, opacity: 0 }}
            transition={{ duration: 0.6, ease: "easeInOut" }}
          >
            <img
              src={`/images/blog/${blogData[current].id}.jpg`}
              alt={blogData[current].title}
              className="blog-slide-image"
            />
            <div className="blog-slide-content">
              <p className="blog-category">Workflow</p>
              <h3 className="blog-title">{blogData[current].title}</h3>
              <p className="blog-summary">{blogData[current].summary}</p>
              <button
                className="blog-read-btn"
                onClick={() => navigate(`/blog/${blogData[current].id}`)}
              >
                read now →
              </button>
            </div>
          </motion.div>
        </AnimatePresence>
      </div>

      <div className="blog-slider-dots">
        {blogData.map((_, i) => (
          <span
            key={i}
            className={`dot ${i === current ? "active" : ""}`}
            onClick={() => setCurrent(i)}
          />
        ))}
      </div>
    </div>
  );
};

export default BlogSlider;
