import React, { useState, useEffect } from "react";
import "./App.css";
import {
  BrowserRouter as Router,
  Routes,
  Route,
} from "react-router-dom";
import { AnimatePresence } from "framer-motion";

// Components
import PhotoCard from "./components/PhotoCard";
import AboutCard from "./components/AboutCard";
import ContactCard from "./components/ContactCard";
import ProjectCard from "./components/ProjectCard";
import IntroCard from "./components/IntroCard";
import ThemeToggleCard from "./components/ThemeToggleCard";
import SocialLinksCard from "./components/SocialLinksCard";
import BlogCard from "./components/BlogCard";
import TechStackCard from "./components/TechStackCard";
import Modal from "./components/Modal";
import AboutModalContent from "./components/AboutModalContent";
import ProjectModalContent from "./components/ProjectModalContent";

// Data
import projectData from "./data/projectData";

// Blog
import BlogPage from "./components/Blog/BlogPage";
import BlogPost from "./pages/BlogPost";
import { BlogThemeProvider } from "./components/Blog/BlogThemeContext";


function App() {
  const [isDarkMode, setIsDarkMode] = useState(() => {
    const saved = localStorage.getItem("dark-mode");
    return saved === null ? true : JSON.parse(saved);
  });

  const [modalOpen, setModalOpen] = useState(false);
  const [modalContent, setModalContent] = useState(null);
  const [selectedProjectId, setSelectedProjectId] = useState(null);

  const selectedProject = projectData.find(
    (project) => project.id === selectedProjectId
  );

  const openModal = (type, id = null) => {
    setModalContent(type);
    setSelectedProjectId(id);
    setModalOpen(true);
  };

  const closeModal = () => {
    setModalOpen(false);
    setSelectedProjectId(null);
  };

  useEffect(() => {
    document.body.style.overflow = modalOpen ? "hidden" : "auto";
  }, [modalOpen]);

  useEffect(() => {
    document.body.className = isDarkMode ? "dark" : "light";
    localStorage.setItem("dark-mode", isDarkMode);
  }, [isDarkMode]);

  const toggleTheme = () => setIsDarkMode((prev) => !prev);

  const portfolio = projectData.find((project) => project.id === "portfolio");
  const mrittika = projectData.find((project) => project.id === "mrittika");

  return (
    <Router>
      <Routes>
        {/* 🏠 Home Page */}
        <Route
          path="/"
          element={
            <div className="app app-container glass-card">
              <div className="grid">
                <IntroCard />
                <ProjectCard
                  project={portfolio}
                  onClick={() => openModal("projects", portfolio.id)}
                />
                <SocialLinksCard />
                <AboutCard onClick={() => openModal("about")} />
                <PhotoCard />
                <BlogCard />
                <ProjectCard
                  project={mrittika}
                  onClick={() => openModal("projects", mrittika.id)}
                />
                <ThemeToggleCard
                  isDarkMode={isDarkMode}
                  toggleTheme={toggleTheme}
                />
                <ContactCard />
                <TechStackCard />
              </div>

              <AnimatePresence>
                {modalOpen && (
                  <Modal isOpen={modalOpen} onClose={closeModal}>
                    {modalContent === "projects" && selectedProject && (
                      <ProjectModalContent project={selectedProject} />
                    )}
                    {modalContent === "about" && (
                      <AboutModalContent onClose={closeModal} />
                    )}
                  </Modal>
                )}
              </AnimatePresence>
            </div>
          }
        />

        {/* 📄 Blog Page with its own theme context */}
        <Route
          path="/blog"
          element={
            <BlogThemeProvider>
              <BlogPage />
            </BlogThemeProvider>
          }
        />

        {/* 📝 Individual Blog Post */}
        <Route
          path="/blog/:id"
          element={
            <BlogThemeProvider>
              <BlogPost />
            </BlogThemeProvider>
          }
        />
      </Routes>
    </Router>
  );
}

export default App;
