// components/Blog/RelatedPosts.js
import React from 'react';
import { Link } from 'react-router-dom';
import blogData from '../../data/blogData';
import './RelatedPosts.css'; // Add this for styling

const RelatedPosts = ({ currentPostId, tags }) => {
  const related = blogData.filter(
    (post) =>
      post.id !== currentPostId &&
      (
        Array.isArray(post.tag)
          ? post.tag.some((tag) => tags?.includes(tag))
          : tags?.includes(post.tag)
      )
  ).slice(0, 10); // get up to 10 related posts

  if (related.length === 0) return null;

  return (
    <div className="related-posts-wrapper">
      <h3 className="related-title">Related Posts</h3>
      <div className="related-posts-row">
        {related.map((post) => (
          <Link to={`/blog/${post.id}`} className="related-post-card" key={post.id}>
            <img src={post.coverImage} alt={post.title} />
            <div className="related-post-info">
              <h4>{post.title}</h4>
              <p>{post.date}</p>
            </div>
          </Link>
        ))}
      </div>
    </div>
  );
};

export default RelatedPosts;
