// BlogMeta.js
import React from 'react';

const BlogMeta = ({ author, date, tag }) => {
  return (
    <div className="blog-meta">
      <h3>Author: {author}</h3>
      <p>Date: {new Date(date).toDateString()}</p>
      <p>Tag: {tag}</p>
      {/* <p>attribution: {attribution}</p> */}
    </div>
  );
};

export default BlogMeta;
